node -e "
const toRad = d => d * Math.PI / 180;

// Current location (San Francisco)
const lat1 = 37.7749, lon1 = -122.4194;

// Boston, MA 02118 (approximate)
const lat2 = 42.3396, lon2 = -71.0640;

// Haversine formula
const R = 6371; // Earth's radius in km
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
const distKm = R * c;
const distMiles = distKm * 0.621371;

console.log('=== Distance Calculation ===');
console.log('From: (37.7749, -122.4194) — San Francisco, CA');
console.log('To:   4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('      (approx. 42.3396, -71.0640)');
console.log('');
console.log('Distance (straight line / great-circle):');
console.log('  ' + distKm.toLocaleString(undefined, {maximumFractionDigits:2}) + ' km');
console.log('  ' + distMiles.toLocaleString(undefined, {maximumFractionDigits:2}) + ' miles');
"
